    merkzettel: [['14. Juli 1789', 'Sturm auf die Bastille'], ['Ballhausschwur', '20. Juni 1789'], ['26. August 1789', 'Menschen- und Bürgerrechte'], ['1792', 'Republik'], ['1793/94', 'Schreckensherrschaft'], ['Leitspruch', 'Freiheit, Gleichheit, Brüderlichkeit']],
