    merkzettel: [['Auslöser', 'Attentat Sarajevo, 28. Juni 1914'], ['Bündnisse', 'Dreibund vs. Entente'], ['Stellungskrieg', 'Verdun, Somme 1916'], ['1917', 'USA treten ein'], ['Waffenstillstand', '11. November 1918'], ['Versailler Vertrag', '1919, Art. 231 Kriegsschuld']],
