    merkzettel: [['Kalter Krieg', 'ca. 1947–1991'], ['NATO', '1949'], ['Warschauer Pakt', '1955'], ['Kubakrise', 'Oktober 1962'], ['Gleichgewicht des Schreckens', 'atomare Abschreckung'], ['Gorbatschow', 'Glasnost, Perestroika']],
